div.script:
        var user = null;
        var pusher = new Pusher('a6980257815c1d1d1e6e', { cluster: 'eu' });
        var channel = pusher.subscribe('github-chat');
        
        channel.bind('message', function(data) {
          var body = document.getElementById('chat-body');
          var login = body.querySelector('.login-screen');
          if (login) login.remove();
          
          var msg = document.createElement('div');
          msg.className = 'message';
          var time = new Date(data.timestamp).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
          var own = user ? (data.username === user.username ? 'own' : '') : '';
          
          msg.innerHTML = '' +
            '
' +
            '
' +
            '@' + data.username + '' +
            '' + time + '' +
            '' +
            '
' + escape(data.text) + '' +
            '';
          
          body.appendChild(msg);
          body.scrollTop = body.scrollHeight;
        });
        
        channel.bind('user-count', function(data) {
          document.getElementById('online-count').textContent = data.count + ' users online';
        });
        
        function openLogin() {
          var w = 600, h = 700;
          var left = (screen.width - w) / 2;
          var top = (screen.height - h) / 2;
          var popup = window.open('https://git-live-chat.vercel.app', 'Login', 'width=' + w + ',height=' + h + ',left=' + left + ',top=' + top);
          
          window.addEventListener('message', function(e) {
            if (e.origin !== 'https://git-live-chat.vercel.app') return;
            if (e.data.type === 'auth-success') {
              user = e.data.user;
              popup.close();
              onLogin();
            }
          });
        }
        
        function onLogin() {
          document.getElementById('login-screen').remove();
          document.getElementById('input-container').style.display = 'block';
          document.getElementById('user-section').innerHTML = 
            '
' +
            '' +
            '@' + user.username + '' +
            '';
          
          fetch('https://git-live-chat.vercel.app/api/join', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ username: user.username, avatar: user.image })
          });
        }
        
        function sendMsg() {
          if (!user) return;
          var input = document.getElementById('message-input');
          var text = input.value.trim();
          if (!text) return;
          
          fetch('https://git-live-chat.vercel.app/api/messages', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              username: user.username,
              avatar: user.image,
              text: text,
              timestamp: new Date().toISOString()
            })
          });
          
          input.value = '';
        }
        
        function escape(text) {
          var div = document.createElement('div');
          div.textContent = text;
          return div.innerHTML;
        }
        
        document.getElementById('message-input').addEventListener('keypress', function(e) {
          if (e.key === 'Enter') sendMsg();
        });
